/**
 *  One plan item linked (via the plan-log `journal_ref`) to a changed-file
 *  group's journal entry. Dogfooding #3 — surfaces "어떤 plan 에서" in the diff.
 */
export type ChangePlanRef = {
	plan_id: string,
	plan_title: string,
	item_title: string,
};

