/**
 *  v2 U10 (C1) — 활성 플랜의 미완 항목 한 건 (스탠드업 "오늘 할 일"/"막힘" 소스).
 *  v2 U12 에서 Today "다음 할 일" 위젯도 이 shape 를 소비한다 (workday brief).
 */
export type OpenPlanItem = {
	plan_id: string,
	plan_title: string,
	item_id: string,
	item_title: string,
	/**  항목이 속한 phase 헤딩 (없으면 None — UI 는 플랜 제목으로 폴백). */
	phase: string | null,
	/**  todo | in_progress | blocked */
	status: string,
};

/**
 *  바이너리를 어느 PATH 에서 찾았는지 — 진단 UI 가 "로그인 셸에서 찾았다"를
 *  보여줘야 사용자가 왜 터미널에선 되는데 앱에선 안 되는지 이해한다.
 */
export type PathSource = 
/**  앱 프로세스가 물려받은 PATH. */
"process" | 
/**  로그인 셸을 띄워 받아온 PATH. */
"login-shell";

